<?php $this->setLayout(''); require __DIR__.'/_layout.php'; ?><section class="panel"><p class="muted">Review every business workspace and suspend or reactivate API access.</p><table><thead><tr><th>Workspace</th><th>Support email</th><th>Currency</th><th>Invoices</th><th>API keys</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?= htmlspecialchars($r['name']) ?></b><br><span class="muted">#<?= (int)$r['id'] ?> · <?= htmlspecialchars($r['slug']) ?></span></td><td><?= htmlspecialchars($r['support_email']??'—') ?></td><td><?= htmlspecialchars($r['default_currency']) ?></td><td><?= (int)$r['invoice_count'] ?></td><td><?= (int)$r['key_count'] ?></td><td><span class="pill <?= $r['status']==='suspended'?'bad':'' ?>"><?= htmlspecialchars($r['status']) ?></span></td><td><form method="post" action="/admin/platform/workspaces/<?= (int)$r['id'] ?>/toggle" onsubmit="return confirm('Change this workspace status?')"><button class="btn <?= $r['status']==='active'?'warn':'' ?>" type="submit"><?= $r['status']==='active'?'Suspend':'Reactivate' ?></button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7" class="empty">No workspaces found.</td></tr><?php endif; ?></tbody></table></section></main></div></body></html>
